// GENERATED by scripts/sync-shared.mjs from src/. Do not edit: change src/ and run `npm run sync:shared`.
// Versus: you against a handful of other people, live, on the same questions.
//
// A match is VERSUS_ROUNDS questions. Everyone sees each question at the same
// moment and has the usual 40 seconds. When the round closes, everyone's
// answers are shown.
//
// Scoring has two parts:
//   1. How rare your answer is in the wider crowd (the same tiers as the daily
//      game, judged against the rule-based ghost crowd for that question).
//   2. If anyone in the match said the same number as you, you split those
//      points between you. Copying the obvious answer gets you very little.
//
// Scores are worked out from the answers alone, so every player's screen
// shows the same numbers without the server having to score anything.
// Shared with the Edge Functions: dependency-free, explicit .ts imports.

import { PROMPTS, getPrompt, isValidAnswer, type Prompt } from '../prompts.ts';
import { GHOST_CONFIG, ABILITIES } from './ghostConfig.ts';
import { abilityDistribution } from './ghostModel.ts';
import { seededRng, shuffle } from './rng.ts';
import { scoreAnswer, type TierId } from './scoring.ts';

export const VERSUS_ROUNDS = 5;
/** Players in a match, you included: 1 v 1 up to 1 v 7. */
export const VERSUS_SIZES = [2, 3, 4, 6, 8] as const;
export type VersusSize = (typeof VERSUS_SIZES)[number];
/** Countdown before the first question. */
export const VERSUS_COUNTDOWN_MS = 4_000;
/** How long everyone's answers stay on screen before the next question. */
export const VERSUS_REVEAL_MS = 9_000;
/** A quick match waits this long for a full table, then starts with whoever came (two or more). */
export const VERSUS_QUICK_WAIT_MS = 45_000;
/** Difficulty of each round, easier first. */
const ROUND_DIFFICULTY = [1, 1, 2, 2, 3] as const;

export const NAME_MAX = 16;

/** Tidy a display name: letters, digits, spaces and a little punctuation, at most 16 characters. */
export function cleanName(raw: string): string {
  return raw
    .normalize('NFKC')
    .replace(/[^\p{L}\p{N} '’.\-_]/gu, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, NAME_MAX)
    .trim();
}

const NAME_START = ['Pencil', 'Ruler', 'Compass', 'Protractor', 'Rubber', 'Chalk', 'Inkwell', 'Abacus', 'Slide Rule', 'Set Square'];

/** A friendly default name, like "Compass 482". */
export function randomName(rng: () => number = Math.random): string {
  return `${NAME_START[Math.floor(rng() * NAME_START.length)]} ${100 + Math.floor(rng() * 900)}`;
}

/** Private room codes: no 0/O or 1/I/L to misread. */
export const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
export const CODE_LENGTH = 5;

export function randomCode(rng: () => number = Math.random): string {
  let code = '';
  for (let i = 0; i < CODE_LENGTH; i++) code += CODE_ALPHABET[Math.floor(rng() * CODE_ALPHABET.length)];
  return code;
}

export function normaliseCode(raw: string): string {
  return raw.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, CODE_LENGTH);
}

/** The match's questions: five different types, getting harder. Deterministic for a seed. */
export function pickVersusPrompts(seed: string, bank: readonly Prompt[] = PROMPTS): string[] {
  const pool = shuffle(bank, seededRng(`outlier-versus:${seed}`));
  const families = new Set<string>();
  const ids: string[] = [];
  for (const want of ROUND_DIFFICULTY) {
    const x = pool.find((p) => p.difficulty === want && !families.has(p.family));
    if (!x) throw new Error('Prompt bank too small for a match');
    families.add(x.family);
    ids.push(x.id);
  }
  return ids;
}

const crowdCache = new Map<string, Map<number, number>>();

/** Share of the ghost crowd giving each valid answer (the ability mix, all styles). */
function crowdShares(prompt: Prompt, year: number): Map<number, number> {
  const key = `${prompt.id}|${year}`;
  let shares = crowdCache.get(key);
  if (!shares) {
    shares = new Map();
    const total = ABILITIES.reduce((s, a) => s + GHOST_CONFIG.abilities[a].share, 0);
    for (const ability of ABILITIES) {
      const weight = GHOST_CONFIG.abilities[ability].share / total;
      const d = abilityDistribution(prompt, ability, { year });
      d.values.forEach((v, i) => shares!.set(v, (shares!.get(v) ?? 0) + weight * d.probs[i]!));
    }
    crowdCache.set(key, shares);
  }
  return shares;
}

/** The crowd's verdict on an answer, before anyone in the match shares it. */
export function crowdScore(prompt: Prompt, value: number, year: number): { tier: TierId; points: number; share: number } {
  if (!isValidAnswer(prompt, value)) return { tier: 'none', points: 0, share: 0 };
  const share = crowdShares(prompt, year).get(value) ?? 0;
  // The same rule as the daily game, against a day's worth of ghosts (1,100) and
  // no other real players, in whole ghosts. Fewer than one expected ghost counts
  // as nobody: that matches how often a sampled daily crowd leaves an answer
  // empty (scripts/simulate-tiers.ts; about 4% Lone Wolf for a strong player).
  const crowd = 1100;
  const expected = share * crowd;
  return scoreAnswer({
    sameReal: 1,
    totalReal: 1,
    sameGhost: expected < 1 ? 0 : Math.max(1, Math.round(expected)),
    totalGhost: crowd,
    ghostCount: crowd,
    realPlayers: 0,
    clever: prompt.cleverList.includes(value),
  });
}

export interface RoundAnswer {
  seat: number;
  /** Null: ran out of time. */
  value: number | null;
}

export interface RoundScore {
  seat: number;
  value: number | null;
  tier: TierId;
  /** Points before splitting. */
  base: number;
  /** Points after splitting with anyone who said the same. */
  points: number;
  /** Other seats that gave the same answer. */
  sharedWith: number[];
}

export function scoreRound(promptId: string, answers: readonly RoundAnswer[], year: number): RoundScore[] {
  const prompt = getPrompt(promptId);
  const bySeat = new Map<number, number[]>();
  for (const a of answers) {
    if (a.value === null) continue;
    bySeat.set(a.value, [...(bySeat.get(a.value) ?? []), a.seat]);
  }
  return answers.map((a) => {
    if (a.value === null) return { seat: a.seat, value: null, tier: 'none', base: 0, points: 0, sharedWith: [] };
    const { tier, points } = crowdScore(prompt, a.value, year);
    const same = bySeat.get(a.value) ?? [a.seat];
    return {
      seat: a.seat,
      value: a.value,
      tier,
      base: points,
      points: Math.round(points / same.length),
      sharedWith: same.filter((s) => s !== a.seat),
    };
  });
}

// ───────────────────────────── Match state ─────────────────────────────

export type MatchKind = 'quick' | 'private' | 'ghosts';
export type MatchStatus = 'waiting' | 'playing' | 'done' | 'abandoned';

export interface VersusPlayer {
  seat: number;
  name: string;
  /** A simulated opponent (ghost matches only). */
  ghost: boolean;
  me: boolean;
  /** Has left the match. */
  left: boolean;
}

export interface VersusRound {
  round: number;
  promptId: string;
  /** Seats that have handed in an answer. */
  answered: number[];
  /** Everyone's answers, once the round has closed. */
  answers: RoundAnswer[] | null;
}

export interface VersusState {
  id: string;
  code: string | null;
  kind: MatchKind;
  size: number;
  status: MatchStatus;
  /** Seat of the player who can start a private room early. */
  hostSeat: number;
  mySeat: number;
  year: number;
  players: VersusPlayer[];
  /** 0 while waiting. */
  round: number;
  /** All times are epoch milliseconds on the server's clock. */
  roundStartsAt: number | null;
  closedAt: number | null;
  /** Quick matches: when the match starts anyway, if two or more are here. */
  startBy: number | null;
  serverNow: number;
  rounds: VersusRound[];
}

export type AnswerOutcome = 'ok' | 'invalid' | 'late' | 'already' | 'not_started' | 'rate_limited';

export interface MatchTotals {
  seat: number;
  total: number;
  /** 1 = winner. Equal totals share a place. */
  place: number;
}

/** Running totals over the closed rounds, best first. */
export function matchTotals(state: Pick<VersusState, 'players' | 'rounds' | 'year'>): MatchTotals[] {
  const totals = new Map(state.players.map((p) => [p.seat, 0]));
  for (const r of state.rounds) {
    if (!r.answers) continue;
    for (const s of scoreRound(r.promptId, r.answers, state.year)) totals.set(s.seat, (totals.get(s.seat) ?? 0) + s.points);
  }
  const sorted = [...totals].sort((a, b) => b[1] - a[1] || a[0] - b[0]);
  return sorted.map(([seat, total]) => ({ seat, total, place: 1 + sorted.filter(([, t]) => t > total).length }));
}

export interface VersusBackend {
  /** 'online' talks to the server; 'local' plays ghosts in the browser. */
  kind: 'online' | 'local';
  quickMatch(name: string, size: number): Promise<string>;
  createRoom(name: string, size: number): Promise<string>;
  joinRoom(name: string, code: string): Promise<string>;
  playGhosts(name: string, size: number): Promise<string>;
  /** Host of a private room: start now with whoever is here. */
  start(matchId: string): Promise<void>;
  leave(matchId: string): Promise<void>;
  state(matchId: string): Promise<VersusState>;
  answer(matchId: string, round: number, value: number): Promise<AnswerOutcome>;
}
